CREATE SEQUENCE IF NOT EXISTS publication_id_seq;
CREATE SEQUENCE IF NOT EXISTS activation_id_seq;
CREATE SEQUENCE IF NOT EXISTS job_id_seq;
CREATE SEQUENCE IF NOT EXISTS completion_id_seq;

CREATE TABLE IF NOT EXISTS checkpoint_contents (
    checkpoint_content_ref TEXT PRIMARY KEY,
    document JSONB NOT NULL
);

CREATE TABLE IF NOT EXISTS publications (
    publication_id TEXT PRIMARY KEY,
    publication_seq BIGINT NOT NULL UNIQUE,
    candidate_id TEXT NOT NULL,
    checkpoint_content_ref TEXT NOT NULL REFERENCES checkpoint_contents(checkpoint_content_ref),
    checkpoint_label TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS publications_candidate_order
    ON publications(candidate_id, publication_seq DESC);

CREATE TABLE IF NOT EXISTS contract_contents (
    contract_content_ref TEXT PRIMARY KEY,
    document JSONB NOT NULL
);

CREATE TABLE IF NOT EXISTS contract_activations (
    activation_id TEXT PRIMARY KEY,
    activation_seq BIGINT NOT NULL UNIQUE,
    contract_content_ref TEXT NOT NULL REFERENCES contract_contents(contract_content_ref),
    contract_label TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS jobs (
    job_id TEXT PRIMARY KEY,
    job_seq BIGINT NOT NULL UNIQUE,
    candidate_id TEXT NOT NULL,
    publication_id TEXT NOT NULL REFERENCES publications(publication_id),
    checkpoint_content_ref TEXT NOT NULL REFERENCES checkpoint_contents(checkpoint_content_ref),
    contract_content_ref TEXT NOT NULL REFERENCES contract_contents(contract_content_ref),
    checkpoint_label TEXT NOT NULL,
    contract_label TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'complete')),
    reused BOOLEAN NOT NULL DEFAULT FALSE,
    resolved_checkpoint_content_ref TEXT REFERENCES checkpoint_contents(checkpoint_content_ref),
    resolved_contract_content_ref TEXT REFERENCES contract_contents(contract_content_ref),
    completed_seq BIGINT
);
CREATE INDEX IF NOT EXISTS jobs_candidate_order ON jobs(candidate_id, job_seq DESC);

CREATE TABLE IF NOT EXISTS seed_results (
    checkpoint_content_ref TEXT NOT NULL REFERENCES checkpoint_contents(checkpoint_content_ref),
    contract_content_ref TEXT NOT NULL REFERENCES contract_contents(contract_content_ref),
    seed BIGINT NOT NULL,
    score BIGINT NOT NULL,
    source_job_id TEXT NOT NULL REFERENCES jobs(job_id),
    PRIMARY KEY (checkpoint_content_ref, contract_content_ref, seed)
);

CREATE TABLE IF NOT EXISTS canonical_results (
    checkpoint_content_ref TEXT NOT NULL REFERENCES checkpoint_contents(checkpoint_content_ref),
    contract_content_ref TEXT NOT NULL REFERENCES contract_contents(contract_content_ref),
    score BIGINT NOT NULL,
    seed_count INTEGER NOT NULL,
    completed_by_job_id TEXT NOT NULL REFERENCES jobs(job_id),
    completed_seq BIGINT NOT NULL UNIQUE,
    PRIMARY KEY (checkpoint_content_ref, contract_content_ref)
);

CREATE TABLE IF NOT EXISTS evaluator_calls (
    call_id BIGSERIAL PRIMARY KEY,
    checkpoint_content_ref TEXT NOT NULL,
    contract_content_ref TEXT NOT NULL,
    seed BIGINT NOT NULL,
    job_id TEXT NOT NULL
);

"""Postgres and Redis access plus schema bootstrap."""

from __future__ import annotations

from contextlib import contextmanager
from pathlib import Path
from typing import Any, Iterator

import psycopg
import redis
from psycopg.rows import dict_row

from .config import DATABASE_URL, REDIS_URL


@contextmanager
def connection() -> Iterator[psycopg.Connection[dict[str, Any]]]:
    with psycopg.connect(DATABASE_URL, row_factory=dict_row) as conn:
        yield conn


def redis_client() -> redis.Redis:
    return redis.Redis.from_url(REDIS_URL, decode_responses=True)


def initialize(reset: bool = False) -> None:
    schema = Path(__file__).with_name("schema.sql").read_text(encoding="utf-8")
    with connection() as conn:
        if reset:
            conn.execute("DROP SCHEMA public CASCADE")
            conn.execute("CREATE SCHEMA public")
        conn.execute(schema)
    if reset:
        redis_client().flushdb()


def next_identifier(conn: psycopg.Connection, kind: str) -> tuple[str, int]:
    allowed = {
        "publication": ("publication_id_seq", "pub"),
        "activation": ("activation_id_seq", "act"),
        "job": ("job_id_seq", "job"),
        "completion": ("completion_id_seq", "completion"),
    }
    if kind not in allowed:
        raise ValueError(f"unknown identifier kind: {kind}")
    sequence, prefix = allowed[kind]
    row = conn.execute(f"SELECT nextval('{sequence}') AS value").fetchone()
    assert row is not None
    value = int(row["value"])
    return f"{prefix}-{value}", value


def current_publication(conn: psycopg.Connection, candidate_id: str) -> dict[str, Any] | None:
    return conn.execute(
        """
        SELECT publication_id, publication_seq, candidate_id,
               checkpoint_content_ref, checkpoint_label
        FROM publications
        WHERE candidate_id = %s
        ORDER BY publication_seq DESC
        LIMIT 1
        """,
        (candidate_id,),
    ).fetchone()


def active_contract(conn: psycopg.Connection) -> dict[str, Any] | None:
    return conn.execute(
        """
        SELECT activation_id, activation_seq, contract_content_ref, contract_label
        FROM contract_activations
        ORDER BY activation_seq DESC
        LIMIT 1
        """
    ).fetchone()


def checkpoint_document(conn: psycopg.Connection, ref: str) -> dict[str, Any]:
    row = conn.execute(
        "SELECT document FROM checkpoint_contents WHERE checkpoint_content_ref = %s",
        (ref,),
    ).fetchone()
    if row is None:
        raise LookupError(f"unknown checkpoint content: {ref}")
    return row["document"]


def contract_document(conn: psycopg.Connection, ref: str) -> dict[str, Any]:
    row = conn.execute(
        "SELECT document FROM contract_contents WHERE contract_content_ref = %s",
        (ref,),
    ).fetchone()
    if row is None:
        raise LookupError(f"unknown contract content: {ref}")
    return row["document"]

"""JSON command-line interface for deterministic platform operations."""

from __future__ import annotations

import argparse
import json
import sys
from typing import Any, Callable

from .db import initialize
from .read_model import clear_result_cache, inspect, leaderboard, metrics
from .scheduler import activate_contract, publish, retry_one, submit
from .worker import process_one


def parser() -> argparse.ArgumentParser:
    root = argparse.ArgumentParser(prog="evalctl")
    commands = root.add_subparsers(dest="command", required=True)

    init_command = commands.add_parser("init")
    init_command.add_argument("--reset", action="store_true")

    publish_command = commands.add_parser("publish")
    publish_command.add_argument("--candidate", required=True)
    publish_command.add_argument("--checkpoint", required=True)

    contract_command = commands.add_parser("activate-contract")
    contract_command.add_argument("--contract", required=True)

    submit_command = commands.add_parser("submit")
    submit_command.add_argument("--candidate", required=True)

    commands.add_parser("process-one")

    retry_command = commands.add_parser("retry-one")
    retry_command.add_argument("--job", required=True)
    retry_command.add_argument("--seed", required=True, type=int)

    commands.add_parser("clear-result-cache")
    commands.add_parser("leaderboard")

    inspect_command = commands.add_parser("inspect")
    inspect_command.add_argument("--candidate")

    commands.add_parser("metrics")
    return root


def execute(arguments: argparse.Namespace) -> dict[str, Any]:
    command = arguments.command
    if command == "init":
        initialize(reset=arguments.reset)
        return {"ok": True}
    if command == "publish":
        return publish(arguments.candidate, arguments.checkpoint)
    if command == "activate-contract":
        return activate_contract(arguments.contract)
    if command == "submit":
        return submit(arguments.candidate)
    if command == "process-one":
        return process_one()
    if command == "retry-one":
        return retry_one(arguments.job, arguments.seed)
    if command == "clear-result-cache":
        return clear_result_cache()
    if command == "leaderboard":
        return leaderboard()
    if command == "inspect":
        return inspect(arguments.candidate)
    if command == "metrics":
        return metrics()
    raise AssertionError(f"unhandled command: {command}")


def main() -> int:
    try:
        result = execute(parser().parse_args())
    except Exception as exc:  # CLI boundary: one diagnostic, nonzero status.
        print(f"evalctl: {exc}", file=sys.stderr)
        return 1
    print(json.dumps(result, sort_keys=True, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Load, validate, and identify checkpoint and evaluation-contract documents."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any


class DocumentError(ValueError):
    pass


def canonical_bytes(document: dict[str, Any]) -> bytes:
    return json.dumps(
        document,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    ).encode("utf-8")


def content_ref(kind: str, document: dict[str, Any]) -> str:
    digest = hashlib.sha256(canonical_bytes(document)).hexdigest()
    return f"{kind}:{digest}"


def load_document(path: str) -> dict[str, Any]:
    candidate = Path(path)
    if not candidate.is_absolute():
        raise DocumentError("document path must be absolute")
    try:
        value = json.loads(candidate.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise DocumentError(f"cannot load JSON document: {exc}") from exc
    if not isinstance(value, dict):
        raise DocumentError("document must be a JSON object")
    return value


def validate_checkpoint(document: dict[str, Any]) -> None:
    required = {"format", "run_id", "checkpoint_name", "actions"}
    if set(document) != required:
        raise DocumentError(f"checkpoint fields must be exactly {sorted(required)}")
    if document["format"] != "tabular-policy-v1":
        raise DocumentError("unsupported checkpoint format")
    if not isinstance(document["run_id"], str) or not document["run_id"]:
        raise DocumentError("run_id must be a non-empty string")
    if not isinstance(document["checkpoint_name"], str) or not document["checkpoint_name"]:
        raise DocumentError("checkpoint_name must be a non-empty string")
    actions = document["actions"]
    if not isinstance(actions, dict) or not actions:
        raise DocumentError("actions must be a non-empty object")
    if not all(isinstance(key, str) and isinstance(value, int) for key, value in actions.items()):
        raise DocumentError("actions must map strings to integers")


def validate_contract(document: dict[str, Any]) -> None:
    required = {
        "format",
        "suite_name",
        "dataset_revision",
        "evaluator_revision",
        "aggregation",
        "seeds",
    }
    if set(document) != required:
        raise DocumentError(f"contract fields must be exactly {sorted(required)}")
    if document["format"] != "evaluation-contract-v1":
        raise DocumentError("unsupported contract format")
    for field in ("suite_name", "dataset_revision", "evaluator_revision"):
        if not isinstance(document[field], str) or not document[field]:
            raise DocumentError(f"{field} must be a non-empty string")
    if document["aggregation"] != "sum":
        raise DocumentError("unsupported aggregation")
    seeds = document["seeds"]
    if not isinstance(seeds, list) or not seeds:
        raise DocumentError("seeds must be a non-empty array")
    seen: set[int] = set()
    for seed_entry in seeds:
        if not isinstance(seed_entry, dict) or set(seed_entry) != {"seed", "cases"}:
            raise DocumentError("each seed must contain exactly seed and cases")
        seed = seed_entry["seed"]
        if not isinstance(seed, int) or seed in seen:
            raise DocumentError("seed values must be unique integers")
        seen.add(seed)
        cases = seed_entry["cases"]
        if not isinstance(cases, list):
            raise DocumentError("cases must be an array")
        for case in cases:
            if not isinstance(case, dict) or set(case) != {
                "observation",
                "expected_action",
                "reward",
            }:
                raise DocumentError(
                    "each case must contain observation, expected_action, and reward"
                )
            if not isinstance(case["observation"], str):
                raise DocumentError("observation must be a string")
            if not isinstance(case["expected_action"], int) or not isinstance(
                case["reward"], int
            ):
                raise DocumentError("expected_action and reward must be integers")


def checkpoint_label(document: dict[str, Any]) -> str:
    return f"{document['run_id']}:{document['checkpoint_name']}"


def contract_label(document: dict[str, Any]) -> str:
    return str(document["suite_name"])

"""Small deterministic policy evaluator used by the runtime."""

from __future__ import annotations

from typing import Any


def seed_score(
    checkpoint: dict[str, Any], contract: dict[str, Any], seed: int
) -> int:
    seed_entry = next(
        (entry for entry in contract["seeds"] if entry["seed"] == seed), None
    )
    if seed_entry is None:
        raise ValueError(f"seed {seed} is not in the evaluation contract")
    actions = checkpoint["actions"]
    return sum(
        case["reward"]
        for case in seed_entry["cases"]
        if actions.get(case["observation"]) == case["expected_action"]
    )

"""Keep the development API running and reload it after source edits."""

from __future__ import annotations

import signal
import subprocess
import sys
import time
from pathlib import Path


SOURCE_DIR = Path(__file__).resolve().parent


def source_snapshot() -> tuple[tuple[str, int], ...]:
    return tuple(
        (path.name, path.stat().st_mtime_ns)
        for path in sorted(SOURCE_DIR.glob("*.py"))
    )


def main() -> int:
    stopping = False
    child: subprocess.Popen[bytes] | None = None

    def stop(_signum: int, _frame: object) -> None:
        nonlocal stopping
        stopping = True
        if child is not None and child.poll() is None:
            child.terminate()

    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)

    while not stopping:
        baseline = source_snapshot()
        child = subprocess.Popen([sys.executable, "-m", "evalstack.api"])
        while not stopping and child.poll() is None:
            time.sleep(0.2)
            if source_snapshot() != baseline:
                child.terminate()
                break
        try:
            child.wait(timeout=5)
        except subprocess.TimeoutExpired:
            child.kill()
            child.wait()
        if not stopping:
            time.sleep(0.2)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

